// Builds apps-script/Golfers.gs from site/players.js so the Sheet's Golfers tab always matches the page.
// Run from the repo root:  node tools/build-golfers.js
global.window = {};
require('../site/players.js');
const D = window.FGT_DATA;
const rows = [];
const seen = new Set();
const sections = D.columns.flat().concat(D.more ? [D.more] : []);
for (const s of sections) {
  for (const name of s.players) {
    if (seen.has(name)) throw new Error('Duplicate golfer: ' + name);
    seen.add(name);
    rows.push([name, s.points, s.label]);
  }
}
const out =
  '// GENERATED by tools/build-golfers.js from site/players.js. Do not edit by hand.\n' +
  "var GOLFERS_VERSION = '" + (D.provisional ? 'provisional' : 'final') + "';\n" +
  'var GOLFERS = ' + JSON.stringify(rows).replace(/\],\[/g, '],\n  [').replace(/^\[\[/, '[\n  [').replace(/\]\]$/, ']\n]') + ';\n';
require('fs').writeFileSync(__dirname + '/../apps-script/Golfers.gs', out);
console.log('Wrote ' + rows.length + ' golfers, version ' + (D.provisional ? 'provisional' : 'final'));
